        int[] b = {4, 6, 1, 3};

        Arrays.sort(a);
        Arrays.sort(b);

        int j = 0;
        for (int i = 0; i < a.length; i++) {
            while (j < b.length && b[j] < a[i]) {
                j++;
            }
            if (j < b.length && b[j] == a[i]) {
                System.out.println("Common element is: " + b[j]);
