#include <iostream>

// Function to find the nth Fibonacci number using recursion
int get_Fibonacci_number(int n) {
    // Base cases for n == 0 and n == 1
    if (n == 0) 
        return 0;
    else if (n == 1) 
        return 1;

    // Recursive call to find the (n-1)th and (n-2)th Fibonacci numbers
    int previous = get_Fibonacci_number(n - 1);
    int second_previous = get_Fibonacci_number(n - 2);

    // Return the sum of the two previous Fibonacci numbers
    return previous + second_previous;
}

int main(void) {
    int number;

    // Ask the user to specify the desired Fibonacci number
    std::cout << "Enter a Fibonacci number: ";
    std::cin >> number;

    // Display the desired Fibonacci number
    std::cout << "The Fibonacci number is: " << get_Fibonacci_number(number) << std::endl;

    return 0;
}
